          if ($urandom_range(0, 1)) begin
            check_error_code(0);
          end
        end else begin
          check_error_code(1);
        end
      end
      // Keep it alive only if needed
      if (!sar_ongoing) begin
        disable sar_simple_thread;
        sar_window.reset();
      end
    end
  join
  sar_window.reset();
  if (cfg.under_reset) return;   // Skip if a reset is ongoing...
  // ensure all msg fifo are written before trigger hmac_process
  if ($urandom_range(0, 1)) begin
    rd_msg_length();
  end
  read_status_intr_clr();
